/**
 * The product scopes and lists on the page: mounting a product root, the live roots a country switch re-renders, and
 * the products the server rendered into the page. Shared by `index.ts` and the optional markets part.
 */
import { cfg, log, warn, reportError } from './config.ts';
import { ProductScope, scopes, rememberOptionNames } from './product.ts';
import { listSelector } from './collection.ts';
import { getProduct, takeStale, refreshProduct, hydrateProducts } from './loader.ts';
import { resolveProductKey, setScopeStatus, isNotFound } from './status.ts';
import { attr, get, qsa, emit } from './dom.ts';
import { toCountry, toLanguage } from './market-codes.ts';
import { isRecord } from '../server/src/shared/json.ts';
import { isProductShape } from './product-shape.ts';
import type { Product } from './fragments.ts';
import type { MountedList } from './collection.ts';
import type { CountryCode, LanguageCode } from './market-codes.ts';

type KeySource = Pick<ReturnType<typeof resolveProductKey>, 'fromUrl' | 'raw'>;

/**
 * The marker on the `<script type="application/json">` tags `tether/server`'s `hydrate()` writes. It is fixed, not
 * `<prefix>-hydrate`, because the server writes it without knowing the browser's prefix.
 */
const HYDRATE_SELECTOR = 'script[type="application/json"][data-tether-hydrate]';

export const mountedProducts = new WeakSet<Element>();
export const mountedLists = new WeakSet<Element>();
/** Product roots to re-render after a country switch; pruned once disconnected. */
export const liveProducts = new Set<HTMLElement>();
/** Lists to reload after a country switch; pruned once disconnected. */
export const liveLists = new Set<MountedList>();
/** Each product root's latest request, so a slow older response can't win. */
const latestRequest = new WeakMap<Element, object>();

/** Forgets roots a page transition removed, so they aren't kept alive. */
export function pruneLive(): void {
  liveProducts.forEach((el) => {
    if (!el.isConnected) liveProducts.delete(el);
  });
  liveLists.forEach((list) => {
    if (!list.root.isConnected) liveLists.delete(list);
  });
}

/** @returns `root` itself when it matches, then the matches inside it. */
export function within(root: ParentNode & Partial<Pick<Element, 'matches'>>, selector: string): HTMLElement[] {
  // A root that matches carries Tether's markup, which goes on HTML elements (see `qsa`).
  const self = root.matches?.(selector) ? [root as HTMLElement] : [];
  return [...self, ...qsa(root, selector)];
}

/** `tether-page-title="{title} | My shop"` on a product root sets `document.title`, for dynamic product pages. */
function applyPageTitle(el: Element, product: Product): void {
  const template = get(el, 'page-title');
  if (!template || typeof document === 'undefined') return;
  const fields = new Map([
    ['title', product.title],
    ['vendor', product.vendor || ''],
    ['type', product.productType || ''],
  ]);
  // One pass with a function replacer, so the shop's text goes in as written: no `$&` or `$$` in it is read as a
  // pattern, and no `{vendor}` inside a title is filled in. An unknown `{name}` stays as it is.
  document.title = template.replace(/\{(\w+)\}/g, (placeholder, name: string) => fields.get(name) ?? placeholder);
}

/**
 * A product root without a key: on a dynamic page opened without `?handle=` (or with an empty path) it is a product
 * that isn't there; inside a list it gets its handle when the list renders.
 */
function mountWithoutKey(el: HTMLElement, { fromUrl, raw }: KeySource): void {
  if (fromUrl) {
    mountedProducts.add(el);
    setScopeStatus(el, 'not-found');
    emit('product-not-found', { key: null, source: raw }, el);
  } else if (!el.closest(listSelector())) {
    warn(`[${attr('product')}] without a value. Bind it to the Shopify handle field, or use "url:handle".`, el);
  }
}

function showLoadFailure(el: HTMLElement, key: string, { fromUrl, raw }: KeySource, error: unknown): void {
  const notFound = isNotFound(error);
  setScopeStatus(el, notFound ? 'not-found' : 'error', error);
  if (!notFound) {
    reportError(error, `product ${key}`);
    emit('error', { error, context: 'product', key }, el);
    return;
  }
  emit('product-not-found', { key, source: raw }, el);
  // A typo in a URL isn't worth an alert; a CMS item pointing at a deleted product is.
  if (fromUrl) log(`product not found: ${key}`);
  else reportError(error, `product ${key}`);
}

/**
 * Mounts one product root.
 *
 * @returns True when a product request was started.
 */
export function mountProduct(el: HTMLElement): boolean {
  if (mountedProducts.has(el)) return false;
  const { key, ...source } = resolveProductKey(el);
  if (!key) {
    mountWithoutKey(el, source);
    return false;
  }
  mountedProducts.add(el);
  liveProducts.add(el);
  const request = {};
  latestRequest.set(el, request);
  const isLatest = () => latestRequest.get(el) === request;
  // A rendered scope keeps showing its content while it refreshes (a country switch).
  if (scopes.get(el)) el.setAttribute(attr('state'), 'updating');
  else setScopeStatus(el, 'loading');
  const loading = trackMarket(getProduct(key));
  loading
    .then((product) => {
      if (!isLatest()) return;
      const existing = scopes.get(el);
      if (existing) existing.update(product);
      else new ProductScope(el, product);
      applyPageTitle(el, product);
      if (cfg.revalidate && takeStale(key)) queueRefresh(key);
    })
    .catch((error: unknown) => {
      if (isLatest()) showLoadFailure(el, key, source, error);
    });
  return true;
}

/** Loads again the product scopes that failed on a network or API error, for when the browser is back online. */
export function retryFailed(): void {
  pruneLive();
  liveProducts.forEach((el) => {
    if (el.getAttribute(attr('state')) !== 'error' || el.getAttribute(attr('error')) === 'not-found') return;
    mountedProducts.delete(el);
    mountProduct(el);
  });
}

/** Server-rendered products to refresh in the next batch. */
let refreshQueue = new Set<string>();

function queueRefresh(key: string): void {
  if (!refreshQueue.size) setTimeout(flushRefresh, 0);
  refreshQueue.add(key);
}

/** @param key The key the refresh was asked for. */
function applyRefresh(key: string, fresh: Product): void {
  liveProducts.forEach((el) => {
    const scope = scopes.get(el);
    if (!scope || !el.isConnected) return;
    const rootKey = resolveProductKey(el).key;
    if (rootKey !== key && rootKey !== fresh.handle && rootKey !== fresh.id) return;
    if (JSON.stringify(scope.product) !== JSON.stringify(fresh)) scope.update(fresh);
  });
}

/** One batched background request refreshes every server-rendered product queued. */
function flushRefresh() {
  const keys = [...refreshQueue];
  refreshQueue = new Set();
  keys.forEach((key) => {
    refreshProduct(key)
      .then((fresh) => {
        applyRefresh(key, fresh);
      })
      .catch((error: unknown) => {
        reportError(error, `refresh ${key}`);
      });
  });
}

/**
 * While the page's server-rendered prices are another market's: the loads to wait for before
 * `html.tether-market-pending` goes. `null` when no market is pending.
 */
let marketPending: Set<Promise<unknown>> | null = null;

/**
 * Lists, and anything else that loads prices, hold `html.tether-market-pending` until they are in.
 *
 * @returns `loading` itself.
 */
export const trackMarket = <T>(loading: Promise<T>): Promise<T> => {
  marketPending?.add(loading);
  return loading;
};

/** After a mount: drops `html.tether-market-pending` once this page's products are live. */
export function settleMarket(): void {
  if (!marketPending) return;
  const waits = [...marketPending];
  void Promise.allSettled(waits).then(() => {
    if (!marketPending || waits.some((wait) => !marketPending?.has(wait))) return;
    if (waits.length !== marketPending.size) {
      settleMarket(); // more loads came in meanwhile
      return;
    }
    marketPending = null;
    document.documentElement.classList.remove(`${cfg.prefix}-market-pending`);
  });
}

/** What `tether/server`'s `hydrate()` writes: the market it fetched in, and the products. */
interface HydratePayload {
  country: CountryCode | undefined;
  language: LanguageCode | undefined;
  products: Product[];
}

/** @param json A hydrate tag's JSON. */
function toHydratePayload(json: unknown): HydratePayload {
  if (!isRecord(json)) return { country: undefined, language: undefined, products: [] };
  const { products } = json;
  const entries: unknown[] = Array.isArray(products) ? products : [];
  return {
    country: toCountry(json['country']) ?? undefined,
    language: toLanguage(json['language']) ?? undefined,
    products: entries.filter(isProductShape),
  };
}

/** Hydrate tags already read. */
const readScripts = new WeakSet<Element>();
/**
 * Uses the products in the page's hydrate tags (`tether/server` `hydrate()`) without a request. A tag made for another
 * market is skipped, and marks the page (`html.tether-market-pending`) until the live prices are in, so CSS can hide
 * prices meanwhile.
 *
 * Trust: a hydrate tag is part of the page, written by the site's own build like the rest of its HTML and scripts, so
 * its prices and products are shown until the background refresh replaces them. Whoever can write a tag into the page
 * can already write a script there; the shape check (`isProductShape`) is for a truncated or hand-written tag, which
 * is skipped instead of failing a render.
 *
 * @param root Where to look: the document for a mount (a tag may sit in `<head>` or anywhere else on the page), the
 *   added elements for `observe`.
 */
export function hydrateFromPage(root: Document | Element = document): void {
  within(root, HYDRATE_SELECTOR).forEach((script) => {
    if (readScripts.has(script)) return;
    readScripts.add(script);
    let json: unknown;
    try {
      json = JSON.parse(script.textContent);
    } catch (error) {
      warn('bad data-tether-hydrate', error);
      return;
    }
    const { country, language, products } = toHydratePayload(json);
    // The build's option names, also for other languages.
    rememberOptionNames(products);
    if (country === cfg.country && language === cfg.language) {
      hydrateProducts(products);
      return;
    }
    log('hydration skipped: other market');
    if (!marketPending) {
      marketPending = new Set();
      document.documentElement.classList.add(`${cfg.prefix}-market-pending`);
    }
  });
}
